//! GV-07: every case of `golden/telemetry/` must produce the recorded output. The files are generated by
//! `tools/golden/gen_telemetry.py` from the Python reference, and each case names the Python test it
//! came from in its `from` field.

use serde_json::{Value, json};
use wg_telemetry::binding::{AttemptRow, BindingFacts, BindingSource, CwdBinding, TargetRow};
use wg_telemetry::binding::{resolve_binding, windows_path};
use wg_telemetry::hook::{CaptureConfig, dedupe_key, normalise, task_keys_in};
use wg_telemetry::json::{dumps_sorted, float_repr};
use wg_telemetry::redact::{redact, redact_text, summarize};
use wg_telemetry::timing::{breakdown, class_names, classify};
use wg_telemetry::transcript::{parse_transcript, split_lines, tool_calls};

const GOLDEN: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../golden/telemetry/");

fn load(file: &str) -> Value {
    let path = format!("{GOLDEN}{file}");
    let text =
        std::fs::read_to_string(&path).unwrap_or_else(|error| panic!("reading {path}: {error}"));
    serde_json::from_str(&text).unwrap_or_else(|error| panic!("parsing {path}: {error}"))
}

fn cases(document: &Value, key: &str) -> Vec<Value> {
    document[key].as_array().cloned().unwrap_or_default()
}

/// Equality with every number compared as a float, since Python writes `0` and `0.0` interchangeably.
fn same(left: &Value, right: &Value) -> bool {
    match (left, right) {
        (Value::Number(a), Value::Number(b)) => match (a.as_f64(), b.as_f64()) {
            (Some(x), Some(y)) => x == y,
            _ => a == b,
        },
        (Value::Array(a), Value::Array(b)) => {
            a.len() == b.len() && a.iter().zip(b).all(|(x, y)| same(x, y))
        }
        (Value::Object(a), Value::Object(b)) => {
            a.len() == b.len()
                && a.iter()
                    .all(|(key, value)| b.get(key).is_some_and(|other| same(value, other)))
        }
        _ => left == right,
    }
}

fn check(id: &str, from: &str, actual: &Value, expected: &Value) {
    assert!(
        same(actual, expected),
        "case {id} ({from}) differs\n actual:   {actual}\n expected: {expected}"
    );
}

fn str_field<'a>(case: &'a Value, key: &str) -> &'a str {
    case[key].as_str().unwrap_or("")
}

fn cap(config: &Value) -> CaptureConfig {
    CaptureConfig {
        capture_tool_payloads: config["capture_tool_payloads"].as_bool().unwrap_or(false),
        max_payload_chars: config["max_payload_chars"].as_u64().unwrap_or(4000) as usize,
    }
}

// covers: P01
#[test]
fn gv07_redaction_text_matches_python() {
    let document = load("redaction.json");
    for case in cases(&document, "text_cases") {
        let id = str_field(&case, "id");
        let max = case["max_chars"].as_u64().map(|value| value as usize);
        let actual = redact_text(str_field(&case, "input"), max);
        check(id, "text_cases", &json!(actual), &case["output"]);
    }
}

/// The input of a case. The golden files are written with `sort_keys`, which loses the insertion order that
/// the Python generator used. The wide-dict cases insert `k0, k1, ...` in numeric order, so for those the
/// order is restored from the numeric key names; every other input is used as written.
fn input_of(case: &Value) -> Value {
    let id = str_field(case, "id");
    match &case["input"] {
        Value::Object(map) if id.contains("wide") => {
            let mut keys: Vec<(u64, &String)> = map
                .keys()
                .map(|key| {
                    (
                        key.trim_start_matches('k')
                            .parse::<u64>()
                            .unwrap_or(u64::MAX),
                        key,
                    )
                })
                .collect();
            keys.sort();
            Value::Object(
                keys.into_iter()
                    .map(|(_, key)| (key.clone(), map[key].clone()))
                    .collect(),
            )
        }
        other => other.clone(),
    }
}

// covers: P01
#[test]
fn gv07_redaction_values_match_python() {
    let document = load("redaction.json");
    for case in cases(&document, "value_cases") {
        let id = str_field(&case, "id");
        let max = case["max_chars"].as_u64().unwrap_or(4000) as usize;
        check(
            id,
            "value_cases",
            &redact(&input_of(&case), max),
            &case["output"],
        );
    }
}

