// covers: P01
#[test]
fn gv07_hook_normalisation_matches_python() {
    let document = load("hook_payload.json");
    for case in cases(&document, "cases") {
        let id = str_field(&case, "id");
        let from = "hook_payload.json cases";
        let config = cap(&case["config_values"]);
        let normalised = normalise(&case["record"], config, "direct")
            .unwrap_or_else(|error| panic!("case {id} rejected: {error:?}"));
        check(
            id,
            from,
            &json!(normalised.event),
            &case["normalised_payload_event"],
        );
        check(id, from, &json!(normalised.dedupe_key), &case["dedupe_key"]);
        check(id, from, &json!(normalised.sanitized), &case["sanitized"]);
        check(
            id,
            from,
            &json!(normalised.tool_summary),
            &case["tool_summary"],
        );
        check(
            id,
            from,
            &json!(normalised.schema_version),
            &case["schema_version"],
        );
    }
}

