// covers: C048
#[test]
fn gv07_transcript_matches_python() {
    let document = load("transcript.json");
    for case in cases(&document, "cases") {
        let id = str_field(&case, "id");
        let from = str_field(&case, "from");
        let lines: Option<Vec<String>> = case["lines"].as_array().map(|items| {
            items
                .iter()
                .map(|line| line.as_str().unwrap_or("").to_owned())
                .collect()
        });
        let sidecar = (!case["sidecar"].is_null()).then(|| case["sidecar"].to_string());
        let stats = parse_transcript(lines.as_deref(), sidecar.as_deref());
        let actual = stats.map_or(Value::Null, |stats| stats.to_json());
        if case["expected"].is_null() {
            assert!(
                stats_is_none(&actual),
                "case {id} ({from}) should be missing"
            );
        } else {
            check(id, from, &actual, &case["expected"]);
        }
    }
}

fn stats_is_none(value: &Value) -> bool {
    value.is_null()
}

// covers: P03
#[test]
fn gv07_tool_calls_match_python() {
    let document = load("transcript.json");
    for case in cases(&document, "cases") {
        let id = str_field(&case, "id");
        let lines: Option<Vec<String>> = case["lines"].as_array().map(|items| {
            items
                .iter()
                .map(|line| line.as_str().unwrap_or("").to_owned())
                .collect()
        });
        let actual: Vec<Value> = tool_calls(lines.as_deref())
            .into_iter()
            .map(|call| json!({"input": call.input, "name": call.name, "tool_use_id": call.tool_use_id}))
            .collect();
        check(id, "tool_calls", &json!(actual), &case["tool_calls"]);
    }
}

// covers: P01
#[test]
fn float_repr_matches_python_repr() {
    let cases = [
        (0.1, "0.1"),
        (100.0, "100.0"),
        (1e16, "1e+16"),
        (1.5e-5, "1.5e-05"),
        (0.0001, "0.0001"),
        (-2.5, "-2.5"),
        (0.0, "0.0"),
        (123_456_789_012_345.6, "123456789012345.6"),
    ];
    for (value, expected) in cases {
        assert_eq!(float_repr(value), expected, "repr of {value:?}");
    }
}

// covers: P01
#[test]
fn json_dumps_is_sorted_and_ascii() {
    assert_eq!(
        dumps_sorted(&json!({"b": 1, "a": ["é", "😀"]})),
        r#"{"a": ["\u00e9", "\ud83d\ude00"], "b": 1}"#
    );
}

// covers: P03
#[test]
fn split_lines_follows_python_splitlines() {
    assert_eq!(split_lines("a\nb\r\nc\rd\n"), vec!["a", "b", "c", "d"]);
    assert_eq!(split_lines("a\n\nb"), vec!["a", "", "b"]);
    assert!(split_lines("").is_empty());
}

// covers: P01
#[test]
fn windows_paths_normalise_like_pathlib() {
    assert_eq!(windows_path("C:/Dev/Rho/"), "C:\\Dev\\Rho");
    assert_eq!(windows_path("C:/"), "C:\\");
    assert_eq!(windows_path(""), ".");
}

// covers: P01
#[test]
fn binding_precedence_and_cwd_prefixes() {
    let facts = BindingFacts {
        env_attempt: Some(AttemptRow {
            workspace_id: "w1".into(),
            attempt_id: "a1".into(),
            task_id: "t1".into(),
        }),
        session_binding: Some(TargetRow {
            workspace_id: "w2".into(),
            task_id: "t2".into(),
        }),
        cwd_bindings: vec![CwdBinding {
            target: TargetRow {
                workspace_id: "w3".into(),
                task_id: "t3".into(),
            },
            prefix: Some("C:/dev/rho".into()),
        }],
        env_task: Some(TargetRow {
            workspace_id: "w4".into(),
            task_id: "t4".into(),
        }),
    };
    let launched = resolve_binding(&facts, Some("s"), Some("C:\\dev\\rho"));
    assert_eq!(launched.source, BindingSource::WorkgraphLaunched);
    assert_eq!(launched.attempt_id.as_deref(), Some("a1"));

    let without_attempt = BindingFacts {
        env_attempt: None,
        ..facts.clone()
    };
    let by_session = resolve_binding(&without_attempt, Some("s"), Some("C:\\dev\\rho"));
    assert_eq!(by_session.task_id.as_deref(), Some("t2"));
    assert_eq!(by_session.source, BindingSource::ExplicitBinding);

    let no_session = BindingFacts {
        session_binding: None,
        ..without_attempt.clone()
    };
    let by_cwd = resolve_binding(&no_session, None, Some("c:\\DEV\\rho\\pkg"));
    assert_eq!(by_cwd.task_id.as_deref(), Some("t3"));
    let sibling = resolve_binding(&no_session, None, Some("c:\\dev\\rhox"));
    assert_eq!(sibling.task_id.as_deref(), Some("t4"));
    assert_eq!(sibling.source, BindingSource::Environment);

    let nothing = BindingFacts::default();
    assert_eq!(
        resolve_binding(&nothing, None, None).source,
        BindingSource::Unbound
    );
    assert_eq!(BindingSource::Unbound.as_str(), "unbound");
}
